    @Test fun memes_conversions_que_aiosendspin() {
        val h = SendspinHorloge()
        for (i in 0 until MES.size / 3) {
            val (m, err, t) = Triple(MES[3 * i], MES[3 * i + 1], MES[3 * i + 2])
            h.maj(m, err, t)
            val vrai = 5_000_000_000L + (t * 50e-6).toLong()
            assertTrue("vers local $i", abs(h.versLocal(t + vrai + 123_456) - ATTENDU[4 * i]) <= 1)
            assertTrue("vers serveur $i", abs(h.versServeur(t + 777) - ATTENDU[4 * i + 1]) <= 1)
            assertEquals("synchro $i", ATTENDU[4 * i + 2] == 1L, h.synchro)
            assertTrue("erreur $i", abs(h.erreur - ATTENDU[4 * i + 3]) <= 1)
        }
    }

    @Test fun mesure_ntp_et_rythme() {
        val h = SendspinHorloge()
        assertFalse(h.synchro); assertEquals(200, h.intervalleMs())
        // Serveur en avance de 1 s, aller-retour de 2 ms (1 ms de chaque côté).
        h.serveurTime(t1 = 10_000, t2 = 1_011_000, t3 = 1_011_100, t4 = 12_100)
        h.serveurTime(t1 = 300_000, t2 = 1_301_000, t3 = 1_301_100, t4 = 302_100)
        assertTrue(h.synchro)
        assertTrue(abs(h.versLocal(2_000_000) - 1_000_000) < 50)
        assertTrue(h.intervalleMs() >= 1_000)
        h.remettre(); assertFalse(h.synchro)
    }
}
